package workspaces

import (
	"strconv"
	"strings"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/git"
	"github.com/anthnel/devdesk/internal/jobs"
	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
)

// This view's knowledge of what is running is a snapshot the router hands it,
// and nothing else (D1). It replaced three maps — scanningPaths, syncingPaths,
// deletingPaths — and the syncRun that counted a batch alongside them.
//
// What the three maps could not do is the whole point: they knew only what this
// view had started. A scan launched on the same repository from `:sec` was
// invisible to busy(), so the guard let a second one through and the two wrote
// the same cache entry. The registry is one bookkeeping, so the guard now
// answers for work started anywhere.

// scanRun builds the run behind S, A and ctrl+a. Label is what `:jobs` shows,
// and the directory being worked in is what identifies the batch to a human.
func (m Model) scanRun(targets []string) jobs.Run {
	return jobs.NewRun(jobs.KindScan, command.ViewWorkspaces, "", m.runLabel(), targets...)
}

func (m Model) syncRun(targets []string) jobs.Run {
	return jobs.NewRun(jobs.KindSync, command.ViewWorkspaces, "", m.runLabel(), targets...)
}

func (m Model) deleteRun(target string) jobs.Run {
	return jobs.NewRun(jobs.KindDelete, command.ViewWorkspaces, "", pathBaseName(target), target)
}

// runLabel names a batch by the directory it was launched in.
func (m Model) runLabel() string {
	if m.currentPath != "" {
		return pathBaseName(m.currentPath)
	}
	return pathBaseName(m.getExpandedWorkspacesDir())
}

// handleJobsChanged takes the router's snapshot. It is the only writer of the
// two fields, and there is nothing to reconcile: the snapshot replaces what was
// held rather than being merged into it.
func (m Model) handleJobsChanged(msg jobs.ChangedMsg) (tea.Model, tea.Cmd) {
	m.jobs = msg.Runs
	m.refreshRows()
	return m, nil
}

// handleFrameMsg takes the animation's frame: the row spinners and the footer.
func (m Model) handleFrameMsg(msg jobs.FrameMsg) (tea.Model, tea.Cmd) {
	m.jobFrame = msg.Frame
	m.footer.SetSpinnerFrame(msg.RenderedFrame)
	m.refreshRows()
	return m, nil
}

// liveRuns returns the runs this view is showing: the ones still going, whatever
// view started them.
//
// Not filtered by origin — that is the point. A scan `:sec` launched on a
// repository listed here spins on its row, because it is the same repository
// and the same work.
func (m Model) liveRuns() []jobs.Run {
	return jobs.Unfinished(m.jobs)
}

// itemState returns where a target stands in the live runs of a kind, and
// whether it is there at all.
func (m Model) itemState(kind jobs.Kind, target string) (jobs.ItemState, bool) {
	for _, run := range m.liveRuns() {
		if run.Kind != kind {
			continue
		}
		for _, item := range run.Items {
			if item.Target == target && !item.State.Terminal() {
				return item.State, true
			}
		}
	}
	return "", false
}

// working reports whether a target is queued or running under any kind.
func (m Model) working(target string) bool {
	for _, run := range m.liveRuns() {
		for _, item := range run.Items {
			if item.Target == target && !item.State.Terminal() {
				return true
			}
		}
	}
	return false
}

// anyWorking reports whether anything at all is going, which is what decides
// whether the footer's progress line carries a spinner.
func (m Model) anyWorking() bool { return len(m.liveRuns()) > 0 }

// workingKind reports whether a target is queued or running under one kind.
func (m Model) workingKind(kind jobs.Kind, target string) bool {
	_, ok := m.itemState(kind, target)
	return ok
}

// scanning, syncing and deleting are the three readings the rows need. They
// replace the three maps one for one, and they read the same source.
func (m Model) scanning(path string) bool { return m.workingKind(jobs.KindScan, path) }
func (m Model) syncing(path string) bool  { return m.workingKind(jobs.KindSync, path) }
func (m Model) deleting(path string) bool { return m.workingKind(jobs.KindDelete, path) }

// ── The footer line (D9) ─────────────────────────────────────────────────────

// jobsStatusLine is what the footer says while work runs. The three forms and
// the reason for the third live with the shared implementation
// (components.JobsStatusLine) — the dashboard says the same sentence now, and
// two copies of a surrender would each be free to surrender differently.
func (m Model) jobsStatusLine() string {
	return sharedcomponents.JobsStatusLine(m.jobs, command.ViewWorkspaces)
}

// ── What each message tells the registry (jobs.Reporter) ─────────────────────
//
// The mapping lives here and not in the router: "a sync that was refused
// because the tree is dirty is a skip, and the reason is worth keeping" is this
// package's vocabulary, and a router that knew it would grow one branch per
// view.

// syncDetailUpdated marks the one settled outcome the item state cannot carry.
// A sync that fast-forwarded and one that had nothing to do are both done; the
// summary counts them apart, and this is the only thing that tells them apart.
const syncDetailUpdated = "updated"

func (m WorkspaceScanStartingMsg) Transition() jobs.Transition {
	// The cancel goes with the state that says the work started, which is the
	// only moment there is anything to stop (D7).
	return jobs.Transition{
		Kind: jobs.KindScan, Target: m.RepoPath,
		State: jobs.ItemRunning, Cancel: m.Cancel,
	}
}

func (m WorkspaceScanCompleteMsg) Transition() jobs.Transition {
	t := jobs.Transition{Kind: jobs.KindScan, Target: m.RepoPath, State: jobs.ItemDone}
	if m.Error != nil {
		t.State = jobs.ItemFailed
		t.Detail = "scan failed — check logs"
	}
	return t
}

func (m WorkspaceSyncStartingMsg) Transition() jobs.Transition {
	return jobs.Transition{Kind: jobs.KindSync, Target: m.RepoPath, State: jobs.ItemRunning}
}

func (m WorkspaceSyncCompleteMsg) Transition() jobs.Transition {
	t := jobs.Transition{Kind: jobs.KindSync, Target: m.RepoPath, State: jobs.ItemDone}
	switch {
	case m.Error != nil:
		t.State = jobs.ItemFailed
		t.Detail = "sync failed — check logs"
	case m.Outcome == git.SyncSkipped:
		// A refusal is not a failure: the fetch happened, the merge did not,
		// and the reason is what the summary names one repository by.
		t.State = jobs.ItemSkipped
		t.Detail = m.Reason
	case m.Outcome == git.SyncUpdated:
		t.Detail = syncDetailUpdated
	}
	return t
}

func (m EntryDeletedMsg) Transition() jobs.Transition {
	t := jobs.Transition{Kind: jobs.KindDelete, Target: m.Path, State: jobs.ItemDone}
	if m.Error != nil {
		t.State = jobs.ItemFailed
		t.Detail = "delete failed — check logs"
	}
	return t
}

// Compile-time proof that every progress message this view emits can be applied
// to the registry. A message added without one would be routed, would update
// the view, and would leave its row spinning for the life of the view — which
// is precisely the failure the registry exists to remove.
var (
	_ jobs.Reporter = WorkspaceScanStartingMsg{}
	_ jobs.Reporter = WorkspaceScanCompleteMsg{}
	_ jobs.Reporter = WorkspaceSyncStartingMsg{}
	_ jobs.Reporter = WorkspaceSyncCompleteMsg{}
	_ jobs.Reporter = EntryDeletedMsg{}
)

// ── The sync summary ─────────────────────────────────────────────────────────

// syncSummary is what the footer says once a sync batch has settled.
//
// It is posted as a footer message rather than derived like the progress line,
// and the difference is Rule 128's own: progress is a state, which is why it
// cannot carry a timer, and an outcome is an event, which is exactly what a
// footer message is. The old code derived both from one struct because they
// shared a function; once progress comes from the registry, they stop needing
// to be the same thing.
func (m Model) syncSummary(run jobs.Run) string {
	var updated, upToDate, skipped, failed int
	var firstSkipped, firstSkippedReason, firstFailed string

	for _, item := range run.Items {
		switch {
		case item.State == jobs.ItemFailed:
			failed++
			if firstFailed == "" {
				firstFailed = pathBaseName(item.Target)
			}
		case item.State == jobs.ItemSkipped:
			// A cancellation lands here too, and its Detail says so: the
			// registry writes "cancelled" on an item that never ran, which
			// reads correctly in "1 skipped (api: cancelled)".
			skipped++
			if firstSkipped == "" {
				firstSkipped = pathBaseName(item.Target)
				firstSkippedReason = item.Detail
			}
		case item.Detail == syncDetailUpdated:
			updated++
		default:
			upToDate++
		}
	}

	var parts []string
	if updated > 0 {
		parts = append(parts, sharedcomponents.Plural(updated, "repository", "repositories")+" updated")
	}
	if upToDate > 0 {
		parts = append(parts, strconv.Itoa(upToDate)+" up to date")
	}
	if skipped > 0 {
		parts = append(parts, strconv.Itoa(skipped)+" skipped ("+firstSkipped+": "+firstSkippedReason+")")
	}
	if failed > 0 {
		parts = append(parts, strconv.Itoa(failed)+" failed ("+firstFailed+") — check logs")
	}
	if m.syncMovedTags > 0 {
		parts = append(parts, sharedcomponents.Plural(m.syncMovedTags, "tag", "tags")+" moved ("+m.syncFirstMovedTag+")")
	}
	if m.syncUnreadable > 0 {
		parts = append(parts, sharedcomponents.Plural(m.syncUnreadable, "directory", "directories")+" unreadable — check logs")
	}
	if len(parts) == 0 {
		return "Nothing to sync"
	}
	return strings.Join(parts, " · ")
}
package workspaces

import (
	"strings"
	"unicode/utf8"

	"github.com/charmbracelet/lipgloss"

	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// Column fixed widths for the workspace table.
const (
	colNameMin = 16
	// colGitMin is the title's width: the cell itself can be as short as a
	// four-letter branch, and a spinner's "⠋ deleting" is ten as well.
	colGitMin = 10
	// colLastTagMin is the title's width. The column grows to the tags it
	// shows, up to colLastTagMax: three version tags like "2.4.2, 2.4, 2" fit,
	// and a longer list is truncated from the right, where the lowest — least
	// specific — version sits.
	colLastTagMin = 10
	colLastTagMax = 24
	// maxTagsShown caps the tags listed for one commit.
	maxTagsShown      = 3
	colSensitiveFixed = 7
	colCFixed         = 4
	colHFixed         = 4
	colMFixed         = 4
	colLFixed         = 4
	colScannedFixed   = 14
	colModFixed       = 15
	colRemoteMin      = 10
	// colCIFixed is four cells for one letter. The title is what costs: "CI
	// Score" is eight to show an A, which is exactly why the four severity
	// columns are called C H M L. A fifth counting column beside them inherits
	// their convention rather than opening a second one.
	colCIFixed = 4
	// colMisconfigFixed is five cells: "CFG" costs three, and the value costs
	// four at worst — three digits and the "?" that says the count is partial.
	colMisconfigFixed = 5
)

// workspaceRow is one line of the table: the entry, plus the six scan cells.
// Those depend on the scan cache, on what is currently scanning and on the
// spinner frame — none of which lives on an Entry, and none of which the
// columns can reach, since they are built once in New. Same shape as
// oci_resources' imageRow, and for the same reason.
type workspaceRow struct {
	Entry Entry
	// GitStatus is the branch and its counts, or the spinner while a sync is
	// rewriting exactly those counts. Showing the stale numbers under a
	// spinner elsewhere in the row would be showing the state being replaced.
	GitStatus string
	// branchCut is how many runes of GitStatus are the branch, which Style
	// colours; TailStyle colours the markers after it. The whole cell while a
	// spinner holds it — there is no branch then, only a status.
	branchCut int
	Sensitive secretsCell
	CI        ciCell
	Misconfig misconfigCell
	Critical  string
	High      string
	Medium    string
	Low       string
	Scanned   string
}

// workspaceColumns describes the workspaces table. Nothing sorts: the order is
// the directory's, and `.` stays inert rather than being wired to a comparator
// no one asked for. Name and Remote are what the filter has always matched.
// ciColumn is the CI grade. It exists only when scan.enable_ci_score is on:
// off, it would be four cells of nothing on every row for the life of the view,
// which says less than no column at all. The setting is read at construction
// and the router drops this view on a save, so the column follows.
//
// It does **not** declare Optional. Its four states include two absences that
// mean different things, and a column that disappeared when the terminal got
// narrow would add a third — "not shown" — indistinguishable from the other
// two. Fewer columns that are right beats every column wrong (§3.45), and this
// one is a verdict rather than a detail.
func ciColumn() datatable.Column[workspaceRow] {
	return datatable.Column[workspaceRow]{
		Title: "CI", Sizing: datatable.SizingFixed, MinWidth: colCIFixed,
		Cell:  func(r workspaceRow) string { return theme.CIScoreCell(r.CI.State, r.CI.Score) },
		Style: func(r workspaceRow) lipgloss.Style { return theme.CIScoreStyle(r.CI.State, r.CI.Score) },
	}
}

// ciCell is what the column prints and what decides its colour, kept apart so
// the colour is never read back off the rendered string — which is what the
// Secrets column used to do and what had to be undone.
type ciCell struct {
	State theme.CIScoreState
	Score *string
}

// misconfigColumn is the misconfiguration count. Like ciColumn it exists only
// when its category is on — off, it would be a dash on every row for the life
// of the view — and like it, it does not declare Optional: a column that
// disappeared on a narrow terminal would be a second absence looking like the
// "-" that means "nobody looked".
//
// It sits after the four severity counters, which count vulnerabilities only,
// and before the grade: that is the order the security inventory uses, and one
// reading order for the same six columns across two views is worth more than
// either placement on its own.
func misconfigColumn() datatable.Column[workspaceRow] {
	return datatable.Column[workspaceRow]{
		Title: "CFG", Sizing: datatable.SizingFixed, MinWidth: colMisconfigFixed,
		Cell: func(r workspaceRow) string { return r.Misconfig.Text },
		Style: func(r workspaceRow) lipgloss.Style {
			return theme.MisconfigStyle(r.Misconfig.State, r.Misconfig.Worst)
		},
	}
}

// misconfigCell is the column's two halves, on secretsCell's model: what it
// prints, and what colours it. The two are not derived from one another — the
// text has cases the state does not, a file and a directory holding no
// repository print nothing at all while a repository nobody scanned prints a
// dash, and all of them colour the same way.
type misconfigCell struct {
	Text  string
	State theme.MisconfigState
	Worst string
}

func workspaceColumns(withCI, withMisconfig bool) []datatable.Column[workspaceRow] {
	text := func(title string, width int, cell func(workspaceRow) string) datatable.Column[workspaceRow] {
		return datatable.Column[workspaceRow]{Title: title, Sizing: datatable.SizingFixed, Optional: true, MinWidth: width, Cell: cell}
	}
	cols := []datatable.Column[workspaceRow]{
		{
			// No title: the column carries a glyph, and a header over it would
			// name something the user reads at a glance anyway — eza does not
			// print one either. It declares neither Less nor Search: it adds no
			// text anyone could type, so the filter stays on Name and Remote.
			Title: "", Sizing: datatable.SizingFixed, MinWidth: datatable.IconColumnWidth,
			Cell:  func(r workspaceRow) string { return entryIcon(r.Entry) },
			Style: func(r workspaceRow) lipgloss.Style { return theme.IconStyle(entryIconRole(r.Entry)) },
		},
		{
			Title: "Name", Sizing: datatable.SizingContent, MinWidth: colNameMin,
			Cell:   func(r workspaceRow) string { return r.Entry.Name },
			Search: func(r workspaceRow) string { return r.Entry.Name },
		},
		{
			Title: "Remote", Sizing: datatable.SizingContent, TruncateHead: true, MinWidth: colRemoteMin, Flex: 1,
			Cell:   func(r workspaceRow) string { return r.Entry.GitRemote },
			Search: func(r workspaceRow) string { return r.Entry.GitRemote },
		},
		{
			// Content-sized: a table of `main` rows used to spend 28 cells on
			// four letters. No MaxWidth — a cap would cut the markers, which
			// are what the column is for; the branch is shortened in the cell
			// instead (gitBranchMaxRunes), so the markers always survive.
			Title: "Git Status", Sizing: datatable.SizingContent, MinWidth: colGitMin,
			Cell:      func(r workspaceRow) string { return r.GitStatus },
			Style:     gitBranchStyle,
			Cut:       func(r workspaceRow) int { return r.branchCut },
			TailStyle: gitMarkersStyle,
		},
		{
			Title: "Last Tag", Sizing: datatable.SizingContent, Optional: true,
			MinWidth: colLastTagMin, MaxWidth: colLastTagMax,
			Cell:  func(r workspaceRow) string { return lastTagsText(r.Entry.GitLastTags) },
			Style: lastTagStyle,
		},
		{
			Title: "Secrets", Sizing: datatable.SizingFixed, MinWidth: colSensitiveFixed,
			Cell:  func(r workspaceRow) string { return r.Sensitive.Text },
			Style: func(r workspaceRow) lipgloss.Style { return theme.SecretsStyle(r.Sensitive.State) },
		},
		count("C", "CRITICAL", colCFixed, func(r workspaceRow) string { return r.Critical }),
		count("H", "HIGH", colHFixed, func(r workspaceRow) string { return r.High }),
		count("M", "MEDIUM", colMFixed, func(r workspaceRow) string { return r.Medium }),
		count("L", "LOW", colLFixed, func(r workspaceRow) string { return r.Low }),
		text("Scanned", colScannedFixed, func(r workspaceRow) string { return r.Scanned }),
		text("Modified", colModFixed, func(r workspaceRow) string { return timeAgo(r.Entry.ModTime) }),
	}
	// Beside the four severity counters, which is where a reader looks for what
	// a scan concluded — not at the end, past Scanned and Modified. Both go in
	// before the last two columns, misconfigurations first, so the order matches
	// the security inventory's.
	var verdicts []datatable.Column[workspaceRow]
	if withMisconfig {
		verdicts = append(verdicts, misconfigColumn())
	}
	if withCI {
		verdicts = append(verdicts, ciColumn())
	}
	if len(verdicts) > 0 {
		tail := append(verdicts, cols[len(cols)-2:]...)
		cols = append(cols[:len(cols)-2], tail...)
	}
	return cols
}

// count builds one of the four severity columns. The cell is already formatted
// by formatScanColumns, so the colour is decided from what it printed: "-" for
// a repository never scanned, "" for something that cannot be, and a number
// otherwise.
//
// Only a non-zero count is coloured. A clean repository showing four coloured
// zeroes reads as four problems at a glance, which is the opposite of what the
// colour is for.
func count(title, severity string, width int, cell func(workspaceRow) string) datatable.Column[workspaceRow] {
	return datatable.Column[workspaceRow]{
		Title: title, Sizing: datatable.SizingFixed, MinWidth: width,
		Cell: cell,
		Style: func(r workspaceRow) lipgloss.Style {
			switch cell(r) {
			case "", "-", "0":
				return theme.DimStyle
			}
			return theme.SeverityTextStyle(severity)
		},
	}
}

// gitBranchStyle colours the branch half of the Git Status cell, and the
// whole cell while a spinner holds it. A branch name is not a verdict, so it
// keeps the table's text colour; only an empty cell is dimmed.
func gitBranchStyle(r workspaceRow) lipgloss.Style {
	if r.Entry.GitBranch == "" {
		return theme.DimStyle
	}
	// No opinion here: the table sets the theme's text color.
	return lipgloss.NewStyle()
}

// gitMarkersStyle warns when F would refuse the repository — uncommitted
// work, untracked files included, or a branch that diverged — so the colour
// says in advance what the sync would report. Anything else is information,
// not a warning, and keeps the text colour: a repository one commit behind is
// the reason F exists, not a problem.
func gitMarkersStyle(r workspaceRow) lipgloss.Style {
	e := r.Entry
	if e.GitModified > 0 || e.GitUntracked > 0 || (e.GitUnpushed > 0 && e.GitUnpulled > 0) {
		return theme.StatusWarningStyle
	}
	return lipgloss.NewStyle()
}

// lastTagsText lists the tags of the nearest tagged commit, at most
// maxTagsShown of them, separated by ", ".
func lastTagsText(tags []string) string {
	return strings.Join(tags[:min(len(tags), maxTagsShown)], ", ")

